import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.CPzUcv0I.js";const m=JSON.parse('{"title":"Algorithme Delta Sync et Sauvegardes Incrémentales","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/horizon/delta-sync-algorithm.md","filePath":"fr/guide/horizon/delta-sync-algorithm.md"}'),o={name:"fr/guide/horizon/delta-sync-algorithm.md"};function i(r,e,l,c,d,u){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="algorithme-delta-sync-et-sauvegardes-incrementales" tabindex="-1">Algorithme Delta Sync et Sauvegardes Incrémentales <a class="header-anchor" href="#algorithme-delta-sync-et-sauvegardes-incrementales" aria-label="Permalink to &quot;Algorithme Delta Sync et Sauvegardes Incrémentales&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Algorithme-Delta%20Diff%C3%A9rentiel-blue.svg" alt="Algorithme"><img src="https://img.shields.io/badge/Hachage-SHA--256-green.svg" alt="Hachage"><img src="https://img.shields.io/badge/Gestion-Consolidation%20Automatique-orange.svg" alt="Gestion"></div><p>Le cœur technologique de Gens-Horizon repose sur son moteur de synchronisation différentielle (<strong>Delta Sync</strong>) implémenté dans <code>scanner.js</code>, <code>upload.js</code>, <code>sync.js</code> et <code>cloud-operations.js</code>.</p><hr><h2 id="_1-balayage-local-haute-performance-scanner-js" tabindex="-1">1. Balayage Local Haute Performance (<code>scanner.js</code>) <a class="header-anchor" href="#_1-balayage-local-haute-performance-scanner-js" aria-label="Permalink to &quot;1. Balayage Local Haute Performance (`scanner.js`)&quot;">​</a></h2><p>Le balayage d&#39;une instance Minecraft (qui peut compter plus de 20 000 fichiers entre les régions du monde, les textures et les mods) doit être quasi-instantané pour ne pas faire attendre le joueur :</p><ol><li><strong>Pré-filtre Rapide (mtime et taille) :</strong> Avant de calculer un hash cryptographique coûteux, le scanner compare la date de dernière modification (<code>mtimeMs</code>) et la taille en octets du fichier par rapport au dernier manifeste connu. Si ces deux valeurs sont identiques, l&#39;ancien hash est conservé sans relecture du disque.</li><li><strong>Hachage SHA-256 en Flux Asynchrone :</strong> Pour les fichiers nouveaux ou modifiés, un hachage SHA-256 est calculé via un flux de lecture Node.js (<code>fs.createReadStream</code>).</li><li><strong>Limiteur de Concurrence (<code>withConcurrency</code>) :</strong> Pour éviter d&#39;épuiser les descripteurs de fichiers système sous Linux ou Windows (<code>EMFILE: too many open files</code>), les lectures de fichiers sont soumises à une file d&#39;attente concurrente bornée (généralement 16 à 32 opérations simultanées maximum).</li></ol><hr><h2 id="_2-detection-des-differences-et-creation-du-delta-upload-js" tabindex="-1">2. Détection des Différences et Création du Delta (<code>upload.js</code>) <a class="header-anchor" href="#_2-detection-des-differences-et-creation-du-delta-upload-js" aria-label="Permalink to &quot;2. Détection des Différences et Création du Delta (`upload.js`)&quot;">​</a></h2><p>Lorsqu&#39;un envoi vers le cloud est déclenché :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Manifeste Local Actuel ]  vs  [ Dernier Manifeste Synchronisé ]</span></span>\n<span class="line"><span>             |                                |</span></span>\n<span class="line"><span>             +----------------+---------------+</span></span>\n<span class="line"><span>                              |</span></span>\n<span class="line"><span>                              v</span></span>\n<span class="line"><span>                [ Différenciation en 3 listes ]</span></span>\n<span class="line"><span>                - Fichiers ajoutés (ADDED)</span></span>\n<span class="line"><span>                - Fichiers modifiés (MODIFIED)</span></span>\n<span class="line"><span>                - Fichiers supprimés (DELETED)</span></span></code></pre></div><ol><li><strong>Génération du Bundle Delta :</strong> Seuls les fichiers marqués <code>ADDED</code> ou <code>MODIFIED</code> sont archivés dans un fichier ZIP nommé selon la convention : <code>GensHorizon_Delta_&lt;timestamp&gt;_&lt;hash&gt;.zip</code></li><li><strong>Métadonnées et Suppressions :</strong> Un fichier de métadonnées léger (<code>GensHorizon_Meta_&lt;timestamp&gt;.json</code>) accompagne l&#39;archive pour lister explicitement les fichiers <code>DELETED</code> qui doivent être supprimés localement sur les autres machines.</li><li><strong>Téléversement Cible :</strong> Le delta (généralement compris entre quelques kilo-octets et 2 Mo) est envoyé vers le dossier distant du fournisseur cloud.</li></ol><hr><h2 id="_3-application-chronologique-des-deltas-sync-js" tabindex="-1">3. Application Chronologique des Deltas (<code>sync.js</code>) <a class="header-anchor" href="#_3-application-chronologique-des-deltas-sync-js" aria-label="Permalink to &quot;3. Application Chronologique des Deltas (`sync.js`)&quot;">​</a></h2><p>Lorsqu&#39;une autre machine se synchronise pour récupérer l&#39;instance :</p><ol><li><strong>Interrogation de l&#39;Index Cloud :</strong><code>sync.js</code> récupère la liste complète des deltas distants via le fournisseur cloud.</li><li><strong>Tri Chronologique :</strong> Tous les deltas postérieurs au dernier état local de la machine sont triés par ordre chronologique strict.</li><li><strong>Application Séquentielle :</strong> Pour chaque delta manquant : <ul><li>L&#39;archive ZIP est téléchargée dans un répertoire temporaire.</li><li>Les fichiers sont extraits et écrasent les anciennes versions locales.</li><li>Les fichiers listés dans les métadonnées de suppression sont retirés du disque.</li><li>Le manifeste local est mis à jour.</li></ul></li><li><strong>Validation de Fin :</strong> L&#39;instance locale est désormais strictement identique à la dernière version jouée sur la machine d&#39;origine.</li></ol><hr><h2 id="_4-nettoyage-et-consolidation-automatique-cloud-operations-js" tabindex="-1">4. Nettoyage et Consolidation Automatique (<code>cloud-operations.js</code>) <a class="header-anchor" href="#_4-nettoyage-et-consolidation-automatique-cloud-operations-js" aria-label="Permalink to &quot;4. Nettoyage et Consolidation Automatique (`cloud-operations.js`)&quot;">​</a></h2><p>Au fil des sessions, le nombre de petits fichiers deltas distants peut augmenter. Pour préserver les quotas de requêtes API et l&#39;espace de stockage :</p><ul><li><strong><code>getCloudIndexAndCleanDuplicates()</code> :</strong> Cette fonction analyse l&#39;arborescence cloud, identifie les fragments obsolètes et supprime les doublons accidentels résultant d&#39;interruptions réseau.</li><li><strong>Seuil de Consolidation (<code>deltaCleanupThreshold</code>) :</strong> Lorsque le nombre de deltas accumulés dépasse le seuil configuré (par défaut 10 sessions), le moteur fusionne l&#39;ensemble de l&#39;historique dans un nouveau point d&#39;ancrage complet (<code>GensHorizon_Backup_&lt;timestamp&gt;.zip</code>) et purge les deltas antérieurs devenus redondants.</li></ul>',20)])])}const h=s(o,[["render",i]]);export{m as __pageData,h as default};
